/* ── Sub-components ── */

function FeatureCard({ icon, color, title, desc }) {
  return (
    <div className={s.featureCard} style={{ '--_accent': color }}>
      <div className={s.featureIconBox} style={{
        background: `color-mix(in srgb, ${color} 8%, transparent)`,
        border: `1px solid color-mix(in srgb, ${color} 19%, transparent)`,
        color,
      }}>{icon}</div>
      <div className={s.featureTitle}>{title}</div>
      <div className={s.featureDesc}>{desc}</div>
    </div>
  )
}

function SpecBlock({ title, items }) {
  return (
    <div className={s.specBlock}>
      <div className={s.specBlockTitle}>{title}</div>
      {items.map((item, i) => (
        <div key={i} className={`${s.specRow} ${i < items.length - 1 ? s.specRowBorder : ''}`}>
          <span className={s.specLabel}>{item.label}</span>
          <span className={s.specValue}>{item.value}</span>
        </div>
      ))}
    </div>
  )
}

function DownloadButton({ platform, icon, sub, href, loading }) {
  return (
    <a
      href={href || '/download'}
      download
      className={`${s.downloadBtn} ${loading ? s.downloadBtnDisabled : ''}`}
    >
      <span className={s.downloadIcon}>{icon}</span>
      <div className={s.downloadTextWrap}>
        <div className={s.downloadPlatform}>Download for {platform}</div>
        <div className={s.downloadSub}>{sub}</div>
      </div>
    </a>
  )
}
